package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class JwksJsonVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property jwks json of trusted client ")
  void test_jwks_json_v_o_builder() {
    Assertions.assertFalse(JwksJsonVO.nullValue().getJwksJson().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(JwksJsonVO.tryFrom(null).getJwksJson().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", JwksJsonVO.from("one").getJwksJson().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> JwksJsonVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", JwksJsonVO.from("one").toString());
  }
}
